/**
 * When a recurrence stops. Mirrors [`cal_core::RecurrenceEnd`], except the
 * `OnDate` date is an ISO `YYYY-MM-DD` string on the FFI boundary (UniFFI has
 * no built-in date type); it is parsed back to a real date when converted into
 * the core model.
 */
sealed class RecurrenceEnd {
    
    /**
     * Repeats forever.
     */
    object Never : RecurrenceEnd()
    
    
    /**
     * Stops after a fixed number of occurrences (`COUNT`).
     */
    data class After(
        val `occurrences`: kotlin.UInt) : RecurrenceEnd()
        
    {
        

        companion object
    }
    
    /**
     * Stops on a date (`UNTIL`), as `YYYY-MM-DD`.
     */
    data class OnDate(
        val `date`: kotlin.String) : RecurrenceEnd()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeRecurrenceEnd : FfiConverterRustBuffer<RecurrenceEnd>{
    override fun read(buf: ByteBuffer): RecurrenceEnd {
        return when(buf.getInt()) {
            1 -> RecurrenceEnd.Never
            2 -> RecurrenceEnd.After(
                FfiConverterUInt.read(buf),
                )
            3 -> RecurrenceEnd.OnDate(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RecurrenceEnd) = when(value) {
        is RecurrenceEnd.Never -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is RecurrenceEnd.After -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`occurrences`)
            )
        }
        is RecurrenceEnd.OnDate -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterString.allocationSize(value.`date`)
            )
        }
    }

    override fun write(value: RecurrenceEnd, buf: ByteBuffer) {
        when(value) {
            is RecurrenceEnd.Never -> {
                buf.putInt(1)
                Unit
            }
            is RecurrenceEnd.After -> {
                buf.putInt(2)
                FfiConverterUInt.write(value.`occurrences`, buf)
                Unit
            }
            is RecurrenceEnd.OnDate -> {
                buf.putInt(3)
                FfiConverterString.write(value.`date`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







/**
 * Error returned when a [`TaskRecurrence`] coming from the foreign side cannot
 * be turned into the core model.
 */
sealed class RecurrenceException: kotlin.Exception() {
    
    /**
     * The `OnDate` end carried a string that is not a valid `YYYY-MM-DD` date.
     */
    class InvalidDate(
        
        val `date`: kotlin.String
        ) : RecurrenceException() {
        override val message
            get() = "date=${ `date` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<RecurrenceException> {
        override fun lift(error_buf: RustBuffer.ByValue): RecurrenceException = FfiConverterTypeRecurrenceError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeRecurrenceError : FfiConverterRustBuffer<RecurrenceException> {
    override fun read(buf: ByteBuffer): RecurrenceException {
        

        return when(buf.getInt()) {
            1 -> RecurrenceException.InvalidDate(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: RecurrenceException): ULong {
        return when(value) {
            is RecurrenceException.InvalidDate -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`date`)
            )
        }
    }

    override fun write(value: RecurrenceException, buf: ByteBuffer) {
        when(value) {
            is RecurrenceException.InvalidDate -> {
                buf.putInt(1)
                FfiConverterString.write(value.`date`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



