    override fun read(buf: ByteBuffer): List<MonthDay> {
        val len = buf.getInt()
        return List<MonthDay>(len) {
            FfiConverterTypeMonthDay.read(buf)
        }
    }

    override fun allocationSize(value: List<MonthDay>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeMonthDay.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<MonthDay>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeMonthDay.write(it, buf)
        }
    }
}




